import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..'))
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..', '..'))
from deckkit import *
import showcase_math as sm

OUT = os.path.join(ROOT, 'premade-cards', '12th', 'Mathematics', 'class12-mathematics-ch04-determinants')
d = Deck('Chapter 4: Determinants', 'Class 12', ['class-12', 'mathematics', 'ch-4'])
d.description = 'Determinants of order 2 and 3, area of a triangle, minors and cofactors, adjoint and inverse, solving linear systems, plus determinant properties and exam-style problems.'
b = d.basic

# ---------------------------------------------------------------- 4.2 Determinant
d.sec('4.2-determinant')
b('What is the determinant of a square matrix?', 'A ' + T('single number') + ' attached to a square matrix A, written det A or |A|. It exists only for square matrices; |A| is a number, A is an array')
b('Determinant of a 1 × 1 and a 2 × 2 matrix?', '|[a]| = ' + T('a') + '. For A = [[a, b], [c, d]]: ' + T('|A| = ad − bc') + ' (main diagonal minus the other diagonal)')
b('Example 1: evaluate |2 4; −1 2|. Ex 4.1 Q1: |2 4; −5 −1|.', '2·2 − 4(−1) = ' + N('8') + '. For Ex 4.1 Q1: 2(−1) − 4(−5) = −2 + 20 = ' + N('18'))
b('Ex 4.1 Q2: evaluate (i) |cos θ −sin θ; sin θ cos θ| and (ii) |x² − x + 1, x − 1; x + 1, x + 1|.', '(i) cos²θ + sin²θ = ' + N('1') + '. (ii) (x² − x + 1)(x + 1) − (x − 1)(x + 1) = (x³ + 1) − (x² − 1) = ' + N('x³ − x² + 2'))
sm.det_area_morph(d)
b('How do you expand a 3 × 3 determinant along the first row?', '|A| = a₁₁ |a₂₂ a₂₃; a₃₂ a₃₃| − a₁₂ |a₂₁ a₂₃; a₃₁ a₃₃| + a₁₃ |a₂₁ a₂₂; a₃₁ a₃₂|. Signs alternate + − +. You can expand along ' + T('any row or column') + ' with the sign pattern (−1)ⁱ⁺ʲ')
b('Which row or column should you expand along?', 'The one with the ' + T('most zeros') + ' (each zero kills a whole 2 × 2 term). Ex 4.1 Q5(i): expand along the second row [0 0 −1]: only one term survives')
b('Ex 4.1 Q3: A = [[1, 2], [4, 2]]. Show |2A| = 4|A|.', '|A| = 2 − 8 = −6. 2A = [[2, 4], [8, 4]] has determinant 8 − 32 = −24 = 4(−6). ' + E('✓') + ' In general |kA| = kⁿ|A| for an n × n matrix')
b('Ex 4.1 Q4: A = [[1, 0, 1], [0, 1, 2], [0, 0, 4]]. Show |3A| = 27|A|.', 'A is upper triangular: |A| = 1·1·4 = 4. 3A has diagonal 3, 3, 12, so |3A| = 108 = 27 · 4. ' + E('✓') + ' (3³ = 27 because n = 3)')
b('Determinant of a triangular or diagonal matrix?', 'The ' + T('product of the diagonal entries') + ' (all zeros on one side of the diagonal). So |I| = 1')
b('Ex 4.1 Q5(i): |3 −1 −2; 0 0 −1; 3 −5 0|.', 'Expand along row 1: 3(0 − 5) + 1(0 + 3) − 2(0 − 0) = −15 + 3 = ' + N('−12') + '. (Row 2 has two zeros, so expanding along it is quicker: only −1 survives.)')
b('Ex 4.1 Q5(ii): |3 −4 5; 1 1 −2; 2 3 1|.', '3(1 + 6) + 4(1 + 4) + 5(3 − 2) = 21 + 20 + 5 = ' + N('46'))
b('Ex 4.1 Q5(iii): |0 1 2; −1 0 −3; −2 3 0|.', '0 − 1(0 − 6) + 2(−3 − 0) = 6 − 6 = ' + N('0') + '. The matrix is skew-symmetric of odd order (a skew-symmetric matrix of odd order always has determinant 0)')
b('Ex 4.1 Q5(iv): |2 −1 −2; 0 2 −1; 3 −5 0|.', '2(0 − 5) + 1(0 + 3) − 2(0 − 6) = −10 + 3 + 12 = ' + N('5'))
b('Ex 4.1 Q6: A = [[1, 1, −2], [2, 1, −3], [5, 4, −9]]. Find |A|.', '1(−9 + 12) − 1(−18 + 15) − 2(8 − 5) = 3 + 3 − 6 = ' + N('0') + ' (so A is singular)')
b('Example 5 / Ex 4.1 Q7(i): find x if |2 4; 5 1| = |2x 4; 6 x|.', '2 − 20 = 2x² − 24 → 2x² = 6 → ' + N('x = ±√3'))
b('Ex 4.1 Q7(ii): find x if |2 3; 4 5| = |x 3; 2x 5|.', '10 − 12 = −2 = 5x − 6x = −x → ' + N('x = 2'))
b('Ex 4.1 Q8: if |x 2; 18 x| = |6 2; 18 6|, then x = (A) 6 (B) ±6 (C) −6 (D) 0', 'x² − 36 = 36 − 36 = 0 → x² = 36 → ' + E('(B) ±6'))
b('Example 5: find x for which |3 x; x 1| = |3 2; 4 1|.', '3 − x² = 3 − 8 → x² = 8 → ' + N('x = ±2√2'))

# ---------------------------------------------------------------- 4.3 Area
d.sec('4.3-area-of-a-triangle')
b('Area of a triangle with vertices (x₁, y₁), (x₂, y₂), (x₃, y₃) as a determinant?', T('Δ = ½ |x₁ y₁ 1; x₂ y₂ 1; x₃ y₃ 1|') + '. Take the ' + T('absolute value') + '; the determinant itself can be negative')
sm.triangle_det_area(d)
b('If the area is given, how do you use the determinant?', 'Set ' + T('½ |...| = ±(area)') + ', i.e. use both signs, and solve for the unknown (Example 7: two values of k)')
sm.collinear_line(d)
b('Condition for three points to be collinear?', T('|x₁ y₁ 1; x₂ y₂ 1; x₃ y₃ 1| = 0') + ' (area zero). The same trick gives the equation of a line through two points: put P(x, y) as the third vertex')
b('Example 7: find the equation of the line through A(1, 3) and B(0, 0) using determinants; find k if D(k, 0) makes area ABD = 3.', '|0 0 1; 1 3 1; x y 1| = 0 → y − 3x = 0: ' + N('y = 3x') + '. Area: ½ |1 3 1; 0 0 1; k 0 1| = ½ |−3k| = 3 → ' + N('k = ±2'))
b('Ex 4.2 Q1(i): area of (1, 0), (6, 0), (4, 3).', '½ |1 0 1; 6 0 1; 4 3 1| = ½ [1(0 − 3) − 0 + 1(18 − 0)] = ½ · 15 = ' + N('15/2'))
b('Ex 4.2 Q1(ii): area of (2, 7), (1, 1), (10, 8).', '½ [2(1 − 8) − 7(1 − 10) + 1(8 − 10)] = ½ (−14 + 63 − 2) = ' + N('47/2'))
b('Ex 4.2 Q1(iii): area of (−2, −3), (3, 2), (−1, −8).', '½ [−2(2 + 8) + 3(−8 + 3) − 1(−3 − 2)] = ½ (−20 − 15 + 5) = ½ (−30). Area is the absolute value: ' + N('15'))
b('Ex 4.2 Q2: show A(a, b + c), B(b, c + a), C(c, a + b) are collinear.', 'Add column 1 to column 2: column 2 becomes (a + b + c) in every row, a multiple of column 3 (all 1s). Two proportional columns ⇒ determinant ' + N('0') + '. ' + E('Collinear'))
b('Ex 4.2 Q3(i): find k if the triangle (k, 0), (4, 0), (0, 2) has area 4.', 'Area = ½ · |k − 4| · 2 = |k − 4| = 4 → ' + N('k = 0 or 8'))
b('Ex 4.2 Q3(ii): find k if the triangle (−2, 0), (0, 4), (0, k) has area 4.', 'Base on the y-axis |4 − k|, height 2: ½ · 2 · |4 − k| = 4 → ' + N('k = 0 or 8'))
b('Ex 4.2 Q4: equation of the line through (i) (1, 2) and (3, 6); (ii) (3, 1) and (9, 3), using determinants.', '(i) |x y 1; 1 2 1; 3 6 1| = x(2 − 6) − y(1 − 3) + (6 − 6) = −4x + 2y = 0 → ' + N('y = 2x') + '. (ii) x(1 − 3) − y(3 − 9) + (9 − 9) = −2x + 6y = 0 → ' + N('x − 3y = 0'))
b('Ex 4.2 Q5: area 35 sq units with vertices (2, −6), (5, 4), (k, 4). Then k = (A) 12 (B) −2 (C) −12, −2 (D) 12, −2', 'Base (5, 4) to (k, 4) has length |k − 5|, height 10: ½ · 10 · |k − 5| = 35 → |k − 5| = 7 → ' + E('(D) 12, −2'))

# ---------------------------------------------------------------- 4.4 Minors and cofactors
d.sec('4.4-minors-and-cofactors')
b('Define the minor of an element aᵢⱼ.', T('Mᵢⱼ') + ' = the determinant left after deleting the i-th row and j-th column')
b('Define the cofactor of aᵢⱼ.', T('Aᵢⱼ = (−1)ⁱ⁺ʲ Mᵢⱼ') + '. Sign pattern for 3 × 3: + − + / − + − / + − +')
sm.cofactor_minor(d)
b('Expansion by cofactors: what is |A| in terms of aᵢⱼ and Aᵢⱼ? What if the cofactors belong to another row?', T('|A| = Σⱼ aᵢⱼ Aᵢⱼ') + ' (any fixed row i or column j). But ' + T('Σⱼ aᵢⱼ Aₖⱼ = 0 for k ≠ i') + ': a row times the cofactors of another row is 0')
b('Ex 4.3 Q5: if Δ = |aᵢⱼ| and Aᵢⱼ is the cofactor of aᵢⱼ, then Δ = (A) a₁₁A₃₁ + a₁₂A₃₂ + a₁₃A₃₃ (B) a₁₁A₁₁ + a₁₂A₂₁ + a₁₃A₃₁ (C) a₂₁A₁₁ + a₂₂A₁₂ + a₂₃A₁₃ (D) a₁₁A₁₁ + a₂₁A₂₁ + a₃₁A₃₁', 'Row or column of elements with the SAME row/column of cofactors: (D) is the first column with its own cofactors. ' + E('(D)'))
b('Ex 4.3 Q1(i): minors and cofactors of |2 −4; 0 3|.', 'M₁₁ = 3, M₁₂ = 0, M₂₁ = −4, M₂₂ = 2. Cofactors: A₁₁ = ' + N('3') + ', A₁₂ = ' + N('0') + ', A₂₁ = ' + N('4') + ', A₂₂ = ' + N('2'))
b('Ex 4.3 Q1(ii): minors and cofactors of |a c; b d|.', 'M₁₁ = d, M₁₂ = b, M₂₁ = c, M₂₂ = a. Cofactors: ' + N('A₁₁ = d, A₁₂ = −b, A₂₁ = −c, A₂₂ = a'))
b('Ex 4.3 Q2(i): minors and cofactors of the 3 × 3 identity.', 'M₁₁ = M₂₂ = M₃₃ = 1 and all other minors 0; cofactors: A₁₁ = A₂₂ = A₃₃ = ' + N('1') + ', others 0 (so the cofactor matrix is I)')
b('Ex 4.3 Q2(ii): cofactors of |1 0 4; 3 5 −1; 0 1 2|.', 'A₁₁ = 11, A₁₂ = −6, A₁₃ = 3; A₂₁ = 4, A₂₂ = 2, A₂₃ = −1; A₃₁ = −20, A₃₂ = 13, A₃₃ = 5. Check: |A| = 1·11 + 0 + 4·3 = ' + N('23'))
b('Ex 4.3 Q3: using cofactors of the second row, evaluate |5 3 8; 2 0 1; 1 2 3|.', 'A₂₁ = −(9 − 16) = 7, A₂₂ = 15 − 8 = 7, A₂₃ = −(10 − 3) = −7. Δ = 2·7 + 0·7 + 1·(−7) = ' + N('7'))
b('Ex 4.3 Q4: using cofactors of the third column, evaluate |1 x yz; 1 y zx; 1 z xy|.', N('(x − y)(y − z)(z − x)') + '. Check with x, y, z = 2, 3, 5: |1 2 15; 1 3 10; 1 5 6| = 6 and (2 − 3)(3 − 5)(5 − 2) = 6 ✓')

# ---------------------------------------------------------------- 4.5 Adjoint and inverse
d.sec('4.5-adjoint-and-inverse')
b('Define the adjoint of a square matrix.', T('adj A = transpose of the cofactor matrix [Aᵢⱼ]') + '. So (adj A)ᵢⱼ = Aⱼᵢ (note the swap)')
b('Shortcut for adj A when A is 2 × 2?', 'For A = [[a, b], [c, d]]: ' + T('adj A = [[d, −b], [−c, a]]') + ' (swap the diagonal, negate the others). Example 12: A = [[2, 3], [1, 4]] gives [[4, −3], [−1, 2]]')
b('Theorem 1: A (adj A) = ?', T('(adj A) A = A (adj A) = |A| I') + '. Reason: a row times its own cofactors gives |A|, times another row’s cofactors gives 0')
b('Define singular and non-singular matrices.', T('Singular') + ': |A| = 0 (e.g. [[1, 2], [4, 8]]). ' + T('Non-singular') + ': |A| ≠ 0')
b('Theorem 4: when is a square matrix invertible? Formula?', 'Iff it is ' + T('non-singular') + ' (|A| ≠ 0), and then ' + T('A⁻¹ = (1/|A|) adj A'))
b('Determinant of a product: |AB| = ?', T('|AB| = |A||B|') + ' (Theorem 3). So AB is non-singular iff both A and B are')
b('|adj A| for an n × n matrix?', T('|adj A| = |A|ⁿ⁻¹') + '. For n = 3: |A|². For n = 2: |A|. (Ex 4.4 Q17: answer (B) |A|²)')
b('If A is invertible, |A⁻¹| = ?', T('1/|A|') + ' since |A||A⁻¹| = |I| = 1 (Ex 4.4 Q18: (B))')
b('Ex 4.4 Q17: A is a non-singular 3 × 3 matrix; |adj A| = (A) |A| (B) |A|² (C) |A|³ (D) 3|A|', E('(B) |A|²') + ' (from |adj A||A| = |A|³)')
b('Ex 4.4 Q18: A invertible of order 2; det(A⁻¹) = (A) det A (B) 1/det A (C) 1 (D) 0', E('(B) 1/det A'))
b('Method: find A⁻¹ using the adjoint (3 × 3).', '1) |A| ≠ 0? 2) all nine cofactors Aᵢⱼ. 3) adj A = transpose of the cofactor matrix. 4) A⁻¹ = adj A / |A|. Verify with A A⁻¹ = I')
steps_card(d, 'Adjoint method · Example 13', 'Find A⁻¹ for A = [[1, 3, 3], [1, 4, 3], [1, 3, 4]].', 'A = [[1, 3, 3], [1, 4, 3], [1, 3, 4]]', [
    '|A| = 1(16 − 9) − 3(4 − 3) + 3(3 − 4) = 7 − 3 − 3 = 1 ≠ 0',
    'Cofactors: A₁₁ = 7, A₁₂ = −1, A₁₃ = −1, A₂₁ = −3, A₂₂ = 1, A₂₃ = 0, A₃₁ = −3, A₃₂ = 0, A₃₃ = 1',
    'adj A = transpose = [[7, −3, −3], [−1, 1, 0], [−1, 0, 1]]',
    'A⁻¹ = adj A / 1 = [[7, −3, −3], [−1, 1, 0], [−1, 0, 1]]'], 3, 'Inverse by the adjoint method', 'A^-1 = adj A / |A|: compute |A|, cofactors, transpose, divide; Example 13: |A| = 1, A^-1 = [[7,-3,-3],[-1,1,0],[-1,0,1]]')

b('Example 15: A = [[2, 3], [1, 2]]. Show A² − 4A + I = O and find A⁻¹.', 'A² = [[7, 12], [4, 7]]; A² − 4A + I = O. Multiply by A⁻¹: A − 4I + A⁻¹ = O so ' + N('A⁻¹ = 4I − A = [[2, −3], [−1, 2]]'))

d.sec('4.5-exercise-4-4')
b('Ex 4.4 Q1: adj of [[1, 2], [3, 4]].', 'Swap the diagonal, negate the rest: ' + N('[[4, −2], [−3, 1]]'))
b('Ex 4.4 Q2: adj of [[1, −1, 2], [2, 3, 5], [−2, 0, 1]].', 'Cofactor matrix then transpose: ' + N('[[3, 1, −11], [−12, 5, −1], [6, 2, 5]]'))
b('Ex 4.4 Q3: verify A(adj A) = |A| I for A = [[2, 3], [−4, −6]].', 'adj A = [[−6, −3], [4, 2]]. A(adj A) = [[−12 + 12, −6 + 6], [24 − 24, 12 − 12]] = O and |A| = −12 + 12 = 0, so |A|I = O. ' + E('✓') + ' (A is singular)')
b('Ex 4.4 Q4: verify A(adj A) = |A| I for A = [[1, −1, 2], [3, 0, −2], [1, 0, 3]].', '|A| = 11. Compute adj A (cofactors) and multiply: every diagonal entry is 11 and every off-diagonal entry 0, i.e. ' + N('11 I') + '. ' + E('✓'))
b('Ex 4.4 Q5: inverse of [[2, −2], [4, 3]].', '|A| = 6 + 8 = 14. A⁻¹ = (1/14)[[3, 2], [−4, 2]] = ' + N('(1/14)[[3, 2], [−4, 2]]'))
b('Ex 4.4 Q6: inverse of [[−1, 5], [−3, 2]].', '|A| = −2 + 15 = 13. ' + N('A⁻¹ = (1/13)[[2, −5], [3, −1]]'))
b('Ex 4.4 Q7: inverse of [[1, 2, 3], [0, 2, 4], [0, 0, 5]].', '|A| = 1·2·5 = 10 (triangular). ' + N('A⁻¹ = (1/10)[[10, −10, 2], [0, 5, −4], [0, 0, 2]]'))
b('Ex 4.4 Q8: inverse of [[1, 0, 0], [3, 3, 0], [5, 2, −1]].', '|A| = 1 · 3 · (−1) = −3. ' + N('A⁻¹ = (−1/3)[[−3, 0, 0], [3, −1, 0], [−9, −2, 3]]'))
b('Ex 4.4 Q9: inverse of [[2, 1, 3], [4, −1, 0], [−7, 2, 1]].', '|A| = 2(−1) − 1(4) + 3(8 − 7) = −3. ' + N('A⁻¹ = (−1/3)[[−1, 5, 3], [−4, 23, 12], [1, −11, −6]]'))
b('Ex 4.4 Q10: inverse of [[1, −1, 2], [0, 2, −3], [3, −2, 4]].', '|A| = 1(8 − 6) + 1(0 + 9) + 2(0 − 6) = −1. ' + N('A⁻¹ = [[−2, 0, 1], [9, 2, −3], [6, 1, −2]]'))
b('Ex 4.4 Q11: inverse of [[1, 0, 0], [0, cos α, sin α], [0, sin α, −cos α]].', '|A| = −cos²α − sin²α = −1. The matrix equals its own inverse: ' + N('A⁻¹ = A') + ' (A² = I)')
b('Ex 4.4 Q12: A = [[3, 7], [2, 5]], B = [[6, 8], [7, 9]]. Verify (AB)⁻¹ = B⁻¹A⁻¹.', 'AB = [[67, 87], [47, 61]], |AB| = 4087 − 4089 = −2, so (AB)⁻¹ = −½[[61, −87], [−47, 67]]. Also A⁻¹ = [[5, −7], [−2, 3]] and B⁻¹ = −½[[9, −8], [−7, 6]]; the product B⁻¹A⁻¹ gives the same matrix. ' + E('✓'))
b('Ex 4.4 Q13: A = [[3, 1], [−1, 2]]. Show A² − 5A + 7I = O and find A⁻¹.', 'A² = [[8, 5], [−5, 3]]. From A² − 5A + 7I = O: A − 5I + 7A⁻¹ = O so ' + N('A⁻¹ = (1/7)(5I − A) = (1/7)[[2, −1], [1, 3]]'))
b('Ex 4.4 Q14: A = [[3, 2], [1, 1]]. Find a, b with A² + aA + bI = O.', 'For 2 × 2: A² − (tr A)A + (det A)I = O with tr A = 4, det A = 1. So ' + N('a = −4, b = 1'))
b('Ex 4.4 Q15: A = [[1, 1, 1], [1, 2, −3], [2, −1, 3]]. Show A³ − 6A² + 5A + 11I = O and find A⁻¹.', 'Multiply by A⁻¹: A² − 6A + 5I + 11A⁻¹ = O, so A⁻¹ = −(1/11)(A² − 6A + 5I). ' + N('A⁻¹ = (1/11)[[−3, 4, 5], [9, −1, −4], [5, −3, −1]]') + ' (|A| = −11)')
b('Ex 4.4 Q16: A = [[2, −1, 1], [−1, 2, −1], [1, −1, 2]]. Verify A³ − 6A² + 9A − 4I = O and find A⁻¹.', 'Multiply by A⁻¹: A² − 6A + 9I = 4A⁻¹. ' + N('A⁻¹ = (1/4)[[3, 1, −1], [1, 3, 1], [−1, 1, 3]]') + ' (|A| = 4)')
b('Method: find A⁻¹ from a matrix equation like A² − 4A + I = O.', 'Multiply the whole equation by A⁻¹ (allowed since |A| ≠ 0), simplify A·A⁻¹ = I, and isolate A⁻¹. This is how Example 15 and Ex 4.4 Q13, Q15, Q16 work')
b('Cayley–Hamilton for a 2 × 2 matrix: what equation does A satisfy?', T('A² − (tr A) A + (det A) I = O') + '. Example: A = [[2, 3], [1, 2]]: tr 4, det 1, so A² − 4A + I = O ✓')

# ---------------------------------------------------------------- 4.6 Linear systems
d.sec('4.6-solving-systems')
b('What is a consistent / inconsistent system?', T('Consistent') + ': at least one solution exists. ' + T('Inconsistent') + ': no solution')
sm.consistency_lines(d)
b('Matrix method for AX = B when |A| ≠ 0?', T('X = A⁻¹ B') + ' (unique solution). Set A = coefficients, X = unknowns, B = constants')
b('When |A| = 0 for AX = B, what do you check?', 'Compute ' + T('(adj A)B') + '. If it is ≠ O: ' + X('inconsistent') + '. If it is = O: the system has either infinitely many solutions or none')
b('Cramer’s rule (beyond the textbook, used in JEE): xᵢ = ?', T('xᵢ = Δᵢ/Δ') + ', where Δ = |A| ≠ 0 and Δᵢ replaces the i-th column of A by B. Faster than the inverse for one unknown')
b('Homogeneous system AX = O: when does it have a non-trivial solution?', 'Iff ' + T('|A| = 0') + '. If |A| ≠ 0 the only solution is x = y = z = 0. (JEE: “find λ so the system has non-trivial solutions” ⇒ set the determinant to 0)')
b('Example 16: solve 2x + 5y = 1, 3x + 2y = 7.', '|A| = −11, X = A⁻¹B = (−1/11)[[2, −5], [−3, 2]][1, 7]ᵀ = (−1/11)[−33, 11]ᵀ: ' + N('x = 3, y = −1'))
b('Example 17: solve 3x − 2y + 3z = 8, 2x + y − z = 1, 4x − 3y + 2z = 4.', '|A| = −17. Cofactors and A⁻¹ = (−1/17) adj A give ' + N('x = 1, y = 2, z = 3'))
b('Example 18: the sum of three numbers is 6; three times the third plus the second is 11; the first plus the third is double the second. Find them.', 'x + y + z = 6, y + 3z = 11, x − 2y + z = 0. |A| = 9, and X = A⁻¹B gives ' + N('1, 2, 3'))
b('Example 19: use the product [[1, −1, 2], [0, 2, −3], [3, −2, 4]] · [[−2, 0, 1], [9, 2, −3], [6, 1, −2]] to solve x − y + 2z = 1, 2y − 3z = 1, 3x − 2y + 4z = 2.', 'The product is I, so the second matrix is A⁻¹. X = A⁻¹B = [−2 + 0 + 2, 9 + 2 − 6, 6 + 1 − 4]ᵀ: ' + N('x = 0, y = 5, z = 3'))

d.sec('4.6-exercise-4-5')
b('Ex 4.5 Q1: is x + 2y = 2, 2x + 3y = 3 consistent?', '|A| = 3 − 4 = −1 ≠ 0: ' + E('consistent') + ' (unique solution x = 0, y = 1)')
b('Ex 4.5 Q2: is 2x − y = 5, x + y = 4 consistent?', '|A| = 2 + 1 = 3 ≠ 0: ' + E('consistent'))
b('Ex 4.5 Q3: is x + 3y = 5, 2x + 6y = 8 consistent?', '|A| = 6 − 6 = 0; adj A = [[6, −3], [−2, 1]], (adj A)B = [30 − 24, −10 + 8]ᵀ = [6, −2]ᵀ ≠ O: ' + X('inconsistent') + ' (parallel lines)')
b('Ex 4.5 Q4: is x + y + z = 1, 2x + 3y + 2z = 2, ax + ay + 2az = 4 consistent?', '|A| = 1(6a − 2a) − 1(4a − 2a) + 1(2a − 3a) = 4a − 2a − a = a ≠ 0, so ' + E('consistent') + ' with a unique solution (for a ≠ 0)')
b('Ex 4.5 Q5: is 3x − y − 2z = 2, 2y − z = −1, 3x − 5y = 3 consistent?', '|A| = 0 and (adj A)B ≠ O: ' + X('inconsistent'))
